// Frozen-before-full-data exact panel/frontier accounting; Ir is NOT wall speed.
#include <nlohmann/json.hpp>
#include <openssl/sha.h>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <map>
#include <array>
#include <vector>
#include <stdexcept>
#include <iostream>
#include <filesystem>
using J=nlohmann::ordered_json;
void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
std::string read(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);need(bool(f),"complete expected receipt required");return{std::istreambuf_iterator<char>(f),{}};}
std::string hash(const std::string&s){unsigned char h[32];SHA256((const unsigned char*)s.data(),s.size(),h);std::ostringstream out;for(auto b:h)out<<std::hex<<std::setw(2)<<std::setfill('0')<<int(b);return out.str();}
bool all_algebraic(const J&p){for(const auto&w:p["works"])if(w["result"]["kind"]!=1)return false;return true;}
int main(int argc,char**argv){try{
 need(argc==6,"analyze ROOT HEAD OLD NEW OUTPUT");std::filesystem::path root=argv[1];std::string head=argv[2];J old,fresh;std::cin>>old>>fresh;need(old["schema"]=="twist.cubic-complete.audit/v1"&&fresh["schema"]=="twist.norm-linear.audit/v1"&&old["profiles"]==1365&&fresh["profiles"]==1365&&fresh["head"]==head,"both complete native mathematical scopes/source");
 std::map<std::array<int,3>,J>math;for(int method:{0,1})for(const auto&p:(method==0?old:fresh)["profiles_data"])if(p["cap"]==(3))need(math.emplace(std::array<int,3>{method,p["route"],p["policy"]},p).second,"duplicate mathematical cell");need(math.size()==2730,"complete math population");
 std::map<std::array<int,4>,unsigned long long>cost;std::map<std::array<int,2>,unsigned long long>aa;J sources=J::array();unsigned long long main_total[2]={0,0},calibration_total[2]={0,0};
 for(int stream=0;stream<2;stream++)for(int index=0;index<38;index++){
  std::ostringstream name;name<<"audit-"<<(stream==0?'A':'B')<<'-'<<std::setw(2)<<std::setfill('0')<<index<<".json";auto bytes=read(root/name.str());J doc=J::parse(bytes);int first=index*12,end=std::min(first+12,455);need(doc["schema"]=="twist.policy-counter-audit.v1"&&doc["head"]==head&&doc["stream"]==(stream==0?"A":"B")&&doc["first_policy"]==first&&doc["end_policy"]==end,"source/scope/stream binding");need(doc["intervals"]==6*(end-first)+3&&doc["warmup_workloads"]==360&&doc["positive_detected"]==true&&doc["negative_within_tolerance"]==true,"complete counter/calibration receipt");aa[{stream,index}]=std::max(1000ULL,doc["aa_instruction_difference"].get<unsigned long long>());sources.push_back(J{{"path",name.str()},{"sha256",hash(bytes)}});
  for(const auto&r:doc["records"]){need(r["original_scalars_checked"]==30,"all targets checked");auto value=r["instruction_reads"].get<unsigned long long>();need(value>0,"positive actual external cost");if(r["label"]!="plain"){calibration_total[stream]+=value;continue;}int method=r["method"],route=r["route"],policy=r["policy"];need(method>=0&&method<2&&route>=3&&route<6&&policy>=first&&policy<end,"case membership");need(cost.emplace(std::array<int,4>{stream,method,route,policy},value).second,"duplicate measured cell");main_total[stream]+=value;}
 }
 need(cost.size()==5460,"every method/role/policy in both streams required");
 auto lo=[&](int m,int r,int p){return std::min(cost.at({0,m,r,p}),cost.at({1,m,r,p}));};auto hi=[&](int m,int r,int p){return std::max(cost.at({0,m,r,p}),cost.at({1,m,r,p}));};auto margin=[&](int p){return std::max(aa.at({0,p/12}),aa.at({1,p/12}));};
 J matched=J::array();for(int route:{3,4,5}){int lower=0,higher=0,overlap=0,all_alg_both=0;J per_policy=J::array();for(int p=0;p<455;p++){auto nlo=lo(1,route,p),nhi=hi(1,route,p),olo=lo(0,route,p),ohi=hi(0,route,p),t=margin(p);lower+=nhi+t<olo;higher+=nlo>ohi+t;overlap+=!(nhi+t<olo)&&!(nlo>ohi+t);bool algebraic=all_algebraic(math.at({1,route,p}))&&all_algebraic(math.at({0,route,p}));all_alg_both+=algebraic;per_policy.push_back(J{{"policy",p},{"new_min_Ir",nlo},{"new_max_Ir",nhi},{"old_min_Ir",olo},{"old_max_Ir",ohi},{"calibration_margin",t},{"both_all30_algebraic",algebraic},{"old_lower_over_new_upper_ratio",(double)olo/(double)nhi}});}matched.push_back(J{{"route",route},{"new_cap",3},{"old_cap",3},{"policies",455},{"repeat_stable_lower_Ir",lower},{"repeat_stable_higher_Ir",higher},{"overlap_or_within_margin",overlap},{"all30_algebraic_both",all_alg_both},{"per_policy",per_policy}});}
 J representations=J::array();for(int source_route:{3,5}){int lower=0,higher=0,overlap=0;for(int p=0;p<455;p++){auto cmin=lo(1,4,p),cmax=hi(1,4,p),smin=lo(1,source_route,p),smax=hi(1,source_route,p),t=margin(p);lower+=cmax+t<smin;higher+=cmin>smax+t;overlap+=!(cmax+t<smin)&&!(cmin>smax+t);}representations.push_back(J{{"updated_source_route",source_route},{"candidate_route",4},{"same_cap",3},{"repeat_stable_candidate_lower_Ir",lower},{"repeat_stable_candidate_higher_Ir",higher},{"overlap_or_within_margin",overlap}});}
 J frontier=J::array();for(bool require_alg:{false,true}){unsigned long long best=~0ULL;int eligible=0,bm=-1,br=-1,bp=-1;for(int m:{0,1})for(int r:{3,5})for(int p=0;p<455;p++){if(require_alg&&!all_algebraic(math.at({m,r,p})))continue;eligible++;auto x=lo(m,r,p);if(x<best){best=x;bm=m;br=r;bp=p;}}int count=0,lower=0,overlap=0,above=0;J candidates=J::array();for(int p=0;p<455;p++){if(require_alg&&!all_algebraic(math.at({1,4,p})))continue;count++;auto low=lo(1,4,p),high=hi(1,4,p),t=margin(p);bool wins=high+t<best;lower+=wins;above+=low>best+t;overlap+=!wins&&!(low>best+t);candidates.push_back(J{{"policy",p},{"min_Ir",low},{"max_Ir",high},{"calibration_margin",t},{"below_nonempty_source_lower_envelope",wins}});}need(eligible>0,"never promote empty source frontier");frontier.push_back(J{{"require_all30_algebraic",require_alg},{"eligible_source_profiles",eligible},{"source_min_lower_Ir",best},{"source_min_method",bm},{"source_min_route",br},{"source_min_policy",bp},{"eligible_candidate_profiles",count},{"candidate_below_source_lower_envelope",lower},{"candidate_above_source_lower_envelope",above},{"candidate_overlap_or_margin",overlap},{"candidates",candidates},{"qualification","finite declared source controls only; post-measurement minimum is diagnostic, no free routing/policy selection or original-S3 degree inference"}});}
 J out={{"schema","twist.full-policy-Ir-description.v1"},{"head",head},{"source_receipts",sources},{"all_policy_main_intervals",5460},{"original_target_workloads_per_stream",81900},{"actual_nonidentity_source_points",30},{"main_Ir_by_stream",J::array({main_total[0],main_total[1]})},{"calibration_Ir_by_stream",J::array({calibration_total[0],calibration_total[1]})},{"same_representation_old_new",matched},{"updated_equal_degree_representation_comparisons",representations},{"full_source_frontier",frontier},{"wall_speed_claim",false},{"intrinsic_regularity_claim",false},{"signed_verdict",false}};
 need(!std::filesystem::exists(argv[5]),"fresh analysis output");std::ofstream f(argv[5]);f<<out.dump()<<'\n';need(bool(f),"analysis write");return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}}
